SET NAMES utf8mb4;


INSERT INTO about (image, title, description, seo_description, seo_title, language)
SELECT image, 'Who Is MSc. Dt. Mehmet Taş?',
'<p>Dentist Mehmet Taş was born in Elbistan, Kahramanmaraş, in 1986. He completed his primary, secondary and high school education in Mersin. He entered the Faculty of Dentistry at Istanbul University in 2004 and graduated from the same faculty in 2009. In 2010 he completed his military service in Tokat as a second lieutenant.</p>
<p>After graduating he worked as a dentist at Özel Tem Hospital for approximately two years. He is one of the founding partners of Özel Denttek Ağız ve Diş Sağlığı Polikliniği, which has been in operation since 2012. In 2020 he completed a master''s degree in the Department of Oral Surgery and Implantology at UniCamillus University in Italy.</p>
<p>He is a member of the Academy of Aesthetic Dentistry Association and of OSSEDER. He works mainly in implant surgery, aesthetic dentistry, smile design and masseter botulinum toxin applications. He speaks English. He has an interest in dental photography; he is married with one child.</p>
<h2>Education and professional background</h2>
<table>
<thead><tr><th>Year</th><th>Stage</th></tr></thead>
<tbody>
<tr><td>2004–2009</td><td>Istanbul University Faculty of Dentistry — undergraduate studies and graduation</td></tr>
<tr><td>2010</td><td>Military service (Tokat, second lieutenant)</td></tr>
<tr><td>2010–2012</td><td>Özel Tem Hospital — dentist</td></tr>
<tr><td>2012</td><td>Özel Denttek Ağız ve Diş Sağlığı Polikliniği — founding partner</td></tr>
<tr><td>2020</td><td>UniCamillus University (Italy) — master''s degree in Oral Surgery and Implantology</td></tr>
</tbody>
</table>
<h2>Professional memberships and areas of interest</h2>
<ul>
<li>Member of the Academy of Aesthetic Dentistry Association</li>
<li>Member of OSSEDER (Osseointegration Society)</li>
<li>Implant surgery and advanced surgical planning</li>
<li>Aesthetic dentistry and smile design</li>
<li>Masseter botulinum toxin — applications to the masticatory muscle in clenching and grinding</li>
<li>Dental photography and case documentation</li>
</ul>
<h2>Clinical approach</h2>
<p>In dentistry a single solution is not right for everyone. Two people presenting with the same complaint may have different plans, because the remaining sound tooth structure, the gum and bone support, the bite relationship, general health and daily care habits all differ from person to person.</p>
<p>The treatment decision is therefore made by assessing together the patient''s account of the complaint, the medical and dental history, the clinical examination and only such imaging as is considered necessary. The purpose of each applicable option, its significant benefits and risks, the alternatives and the likely consequences of leaving the condition untreated are all discussed in plain language. Informed consent is not merely a signature; it is a process of clear explanation and of being able to ask questions.</p>
<p>In comprehensive treatment, procedures are divided into stages: first emergency and infection control, then arresting the disease and establishing basic gum health, followed by definitive restorative, surgical or prosthetic stages, and finally the maintenance and check-up routine. For the detail of this process see <a href="/en/tedavi-plani-ve-surec/">Treatment Plan and Process</a>, and for what is assessed at the first examination see <a href="/en/ilk-dis-muayenesi-tedavi-planlamasi/">First Dental Examination and Treatment Planning</a>.</p>
<h2>Our clinical team</h2>
<p>Our clinic has dentists working in implantology and oral surgery, endodontics, paediatric dentistry, orthodontics, and restorative and prosthetic dentistry. All treatments within the field of dentistry are carried out within our clinic. For the full clinical team: <a href="https://denttek.com.tr/hekimlerimiz/" target="_blank" rel="noopener">Özel Denttek — Our Dentists</a></p>
<h2>Frequently asked questions</h2>
<p><strong>In which fields does MSc. Dt. Mehmet Taş work?</strong><br>He works mainly in implant surgery, oral surgery and aesthetic dentistry. Procedures in endodontics, paediatric dentistry, orthodontics and restorative and prosthetic dentistry are carried out together with the relevant colleagues at the clinic.</p>
<p><strong>In which field is his master''s degree?</strong><br>It was completed in Oral Surgery and Implantology at UniCamillus University in Italy (2020).</p>
<p><strong>Is masseter botulinum toxin within the scope of dentistry?</strong><br>Yes. In people whose masticatory muscle is overworked and enlarged because of clenching and grinding (bruxism), botulinum toxin application is a treatment option directed at the jaw and facial region. The decision is made by considering the bite assessment, examination of the muscles and joint, and signs of wear together, and it is often assessed alongside options such as a night guard.</p>
<p><strong>Can I come for a second opinion?</strong><br>Yes. Seeking a second opinion is the patient''s right. Bringing your existing radiographs, reports and treatment records makes the assessment easier.</p>
<p><strong>Can the consultation be held in English?</strong><br>Yes, the dentist speaks English.</p>
<p><strong>How are my treatment records kept?</strong><br>Information obtained during examination, imaging and treatment is special category personal data. The purposes for which it is processed and the rights you hold are explained in the <a href="/en/sayfa/kvkk-aydinlatma-metni">personal data protection notice</a>.</p>
<h2>Local assessment</h2>
<p>At our clinic at the Beylikdüzü–Esenyurt junction, the treatment plan is drawn up by assessing the clinical examination, the necessary imaging and the patient''s expectations together, and it is shared with the patient.</p>
<p><a href="/en/tedaviler">Treatment topics</a> &middot; <a href="/en/implant/">Dental Implant Treatment</a> &middot; <a href="/en/estetik/">Aesthetic Dentistry</a> &middot; <a href="/en/iletisim">Appointments and contact</a></p>',
'The education of Dr Mehmet Taş, his master''s degree in Oral Surgery and Implantology, his clinical experience and his approach to treatment.',
'Who Is MSc. Dt. Mehmet Taş? | Education and Clinical Approach',
'EN' FROM about WHERE language = 'TR';

