INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Personal Data Protection Notice',
'<p>This notice has been prepared by Dt. Mehmet Taş, acting as data controller, in accordance with Turkish Law no. 6698 on the Protection of Personal Data (“KVKK”), concerning the processing of the personal data of visitors who use the contact and appointment request form on the dtmehmettas.com.tr website.</p>
<h2>Data Controller</h2>
<p>Dt. Mehmet Taş — Cumhuriyet Mah. Nazım Hikmet Blv. No: 89/2, Esenyurt / İstanbul. E-mail: info@dtmehmettas.com.tr, Telephone: +90 543 558 85 19.</p>
<h2>Personal Data Processed</h2>
<p>Through the contact form we process only your name and surname, telephone number, e-mail address (optional) and the information you write in the message field. No health data, diagnosis or treatment information is requested through this form; we advise you not to write such information in the message field.</p>
<h2>Purposes of Processing</h2>
<p>Your personal data is processed for the purposes of receiving contact and appointment requests, responding to your request, providing information about scheduling an examination, and keeping a record of requests. Your data is not used for advertising or marketing purposes and is not shared with third parties for commercial purposes.</p>
<h2>Legal Basis and Method of Collection</h2>
<p>Your data is collected electronically through the form on the website and is processed on the legal bases set out in Article 5 of the KVKK, namely that processing “is directly related to the conclusion or performance of a contract” and that it “is necessary for the legitimate interests of the data controller, provided that it does not harm the fundamental rights and freedoms of the data subject”.</p>
<h2>Transfer</h2>
<p>Form data is stored with the hosting service provider on which the website is hosted. It is not transferred to third parties in Turkey or abroad unless there is a legal obligation to do so.</p>
<h2>Retention Period</h2>
<p>Data relating to a contact request is retained for a maximum of one year from the conclusion of the request, after which it is deleted or anonymised. Where a request becomes a patient record, the retention periods set out in health legislation apply.</p>
<h2>Your Rights as a Data Subject</h2>
<p>Under Article 11 of the KVKK you have the right to: learn whether your personal data is being processed; request information if it has been processed; learn the purpose of processing and whether the data is used in accordance with that purpose; know the third parties to whom it has been transferred; request correction if it has been processed incompletely or inaccurately; request its erasure or destruction; request that these actions be notified to the third parties to whom the data was transferred; object to a result arising against you from analysis carried out exclusively by automated systems; and claim compensation if you suffer loss as a result of unlawful processing. You may submit your applications in writing to the contact details above; applications are concluded within 30 days at the latest.</p>
<p><em>This English text is provided for information. In the event of any inconsistency, the Turkish version of this notice prevails.</em></p>
<p><em>Last updated: 21.09.2026</em></p>',
'Personal data protection notice for data collected through the contact and appointment form on dtmehmettas.com.tr.',
'Personal Data Protection Notice | MSc. Dt. Mehmet Taş',
'EN' FROM pages WHERE link = 'kvkk-aydinlatma-metni';

